ICON_PNG_B64 = ''
ICON_ICO_B64 = ''


def replace_once(content: str, old: str, new: str, label: str) -> str:
    if new in content:
        print(f"[skip] already patched: {label}")
        return content
    count = content.count(old)
    if count != 1:
        raise RuntimeError(f"Expected exactly 1 match for {label}, found {count}")
    print(f"[ok] patched: {label}")
    return content.replace(old, new, 1)


def replace_optional(content: str, old: str, new: str, label: str) -> str:
    if new in content:
        print(f"[skip] already patched: {label}")
        return content
    if old not in content:
        print(f"[info] skipped (not present): {label}")
        return content
    print(f"[ok] patched: {label}")
    return content.replace(old, new, 1)


def extract_wg_socks(out_dir: pathlib.Path) -> None:
    out_dir.mkdir(parents=True, exist_ok=True)
    for name, payload in WG_SOCKS_FILES.items():
        target = out_dir / name
        target.write_bytes(base64.b64decode(payload))
        print(f"[ok] wrote {target} ({target.stat().st_size} bytes)")


def apply_pocketdesk_icons(repo_root: pathlib.Path) -> None:
    png_bytes = base64.b64decode(ICON_PNG_B64)
    ico_bytes = base64.b64decode(ICON_ICO_B64)

    png_targets = [
        repo_root / "flutter" / "assets" / "icon.png",
    ]
    for p in png_targets:
        if p.parent.exists():
            p.write_bytes(png_bytes)
            print(f"[ok] wrote icon {p} ({len(png_bytes)} bytes)")

    ico_targets = [
        repo_root / "flutter" / "windows" / "runner" / "resources" / "app_icon.ico",
        repo_root / "res" / "tray-icon.ico",
        repo_root / "res" / "icon.ico",
    ]
    for p in ico_targets:
        if p.exists() or p.parent.exists():
            p.write_bytes(ico_bytes)
            print(f"[ok] wrote ico {p} ({len(ico_bytes)} bytes)")

    # Update Windows Runner.rc product metadata to PocketDesk
    runner_rc = repo_root / "flutter" / "windows" / "runner" / "Runner.rc"
    if runner_rc.exists():
        raw = runner_rc.read_text(encoding="utf-8", errors="ignore")
        raw = raw.replace('"RustDesk Remote Desktop"', '"PocketDesk Remote Desktop"')
        raw = raw.replace('"ProductName", "RustDesk"', '"ProductName", "PocketDesk"')
        raw = raw.replace('"CompanyName", "Purslane Tech Pte. Ltd."', '"CompanyName", "PocketDesk"')
        runner_rc.write_text(raw, encoding="utf-8")
        print(f"[ok] branded {runner_rc}")


